using MiniStore.Application.Dtos.Accounting;
using MiniStore.Application.Services;
using MiniStore.Domain.Entities;
using MiniStore.Domain.Interfaces;
using MiniStore.Domain.Interfaces.Accounting;
namespace MiniStore.Application.Services.Accounting;
public sealed class BankReconciliationService(IBankReconciliationRepository repository,IUnitOfWork unitOfWork,SemanticAuditEventService audit)
{
 public async Task MatchAsync(MatchBankStatementDto dto)=>await unitOfWork.ExecuteInTransactionAsync(async()=>
 { var statement=await repository.GetStatementLineAsync(dto.StatementLineId)??throw new ArgumentException("Statement line was not found."); if(dto.StatementLineRowVersion.Length==0||!statement.RowVersion.SequenceEqual(dto.StatementLineRowVersion))throw new InvalidOperationException("Statement line was modified by another user. Reload and try again."); await EnsureStatementCapacityAsync(dto.StatementLineId,dto.Amount); await EnsureJournalCompatibilityAsync(dto.StatementLineId,dto.JournalEntryLineId,dto.Amount); await repository.AddAsync(new BankReconciliationAllocation(dto.StatementLineId,dto.JournalEntryLineId,dto.Amount));statement.TouchReconciliation(DateTime.UtcNow); await repository.SaveChangesAsync(); await audit.RecordTenantSuccessAsync(AuditEventCategory.Operations,SemanticAuditEventTypes.BankStatementMatched,"Match","BankStatementLine",dto.StatementLineId.ToString(),afterValues:new Dictionary<string,object?>{{"journalEntryLineId",dto.JournalEntryLineId},{"amount",dto.Amount}}); });
 public async Task<BankReconciliationStateDto> GetStateAsync(int statementLineId){var allocations=await repository.GetAllocationsAsync(statementLineId);return new(statementLineId,await GetStatementRemainingAsync(statementLineId),allocations.Select(x=>new BankReconciliationAllocationDto(x.Id,x.JournalEntryLineId,x.Amount,x.IsActive,x.UnmatchReason,x.RowVersion)).ToList());}
 public async Task UnmatchAsync(UnmatchBankStatementDto dto)=>await unitOfWork.ExecuteInTransactionAsync(async()=>{var allocation=await repository.GetAllocationAsync(dto.AllocationId)??throw new ArgumentException("Allocation was not found.");if(dto.RowVersion.Length==0||!allocation.RowVersion.SequenceEqual(dto.RowVersion))throw new InvalidOperationException("Allocation was modified by another user. Reload and try again.");var statement=await repository.GetStatementLineAsync(allocation.BankStatementLineId)??throw new InvalidOperationException("Statement line was not found.");allocation.Unmatch(dto.Reason);statement.TouchReconciliation(DateTime.UtcNow);await repository.SaveChangesAsync();await audit.RecordTenantSuccessAsync(AuditEventCategory.Operations,SemanticAuditEventTypes.BankStatementUnmatched,"Unmatch","BankReconciliationAllocation",dto.AllocationId.ToString(),afterValues:new Dictionary<string,object?>{{"reason",dto.Reason}});});
 public async Task<decimal> GetStatementRemainingAsync(int lineId){var line=await repository.GetStatementLineAsync(lineId)??throw new ArgumentException("Statement line was not found.");return Math.Max(0m,(line.Debit+line.Credit)-(await repository.GetActiveStatementAllocationAsync(lineId)));}
 public async Task EnsureStatementCapacityAsync(int lineId,decimal amount){if(amount<=0)throw new ArgumentException("Match amount must be positive.");if(amount>await GetStatementRemainingAsync(lineId))throw new InvalidOperationException("Match amount exceeds the remaining statement-line amount.");}
 public async Task EnsureJournalCompatibilityAsync(int statementLineId,int journalLineId,decimal amount){var statement=await repository.GetStatementLineAsync(statementLineId)??throw new ArgumentException("Statement line was not found.");var journal=await repository.GetJournalLineAsync(journalLineId)??throw new ArgumentException("Journal line was not found.");var bankAccountId=await repository.GetStatementAccountIdAsync(statementLineId);if(!bankAccountId.HasValue||journal.Line.AccountId!=bankAccountId.Value)throw new InvalidOperationException("The journal line must use the linked bank ledger account.");if(journal.Status!=JournalEntryStatus.Posted)throw new InvalidOperationException("Only posted journal lines can be matched.");if((statement.Debit>0)!=(journal.Line.Debit>0))throw new InvalidOperationException("Statement and journal directions must match.");var remaining=Math.Max(0m,(journal.Line.Debit+journal.Line.Credit)-(await repository.GetActiveJournalAllocationAsync(journalLineId)));if(amount>remaining)throw new InvalidOperationException("Match amount exceeds the remaining journal-line amount.");}
}
